cypress_script:
describe('Login Page', () => {
  it('should log in with valid credentials', () => {
    cy.visit('https://www.saucedemo.com/');
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();
    cy.url().should('not.eq', 'https://www.saucedemo.com/');
  });

  it('should not log in with empty credentials', () => {
    cy.visit('https://www.saucedemo.com/');
    cy.get('[data-test="login-button"]').click();
    cy.url().should('eq', 'https://www.saucedemo.com/');
    cy.get('[data-test="login-container"]').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Login Page', () => {
  test('should log in with valid credentials', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/');
    await page.fill('[data-test="username"]', 'standard_user');
    await page.fill('[data-test="password"]', 'secret_sauce');
    await page.click('[data-test="login-button"]');
    await expect(page).toHaveURL(/^(?!.*saucedemo.com).*/);
  });

  test('should not log in with empty credentials', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/');
    await page.click('[data-test="login-button"]');
    await expect(page).toHaveURL('https://www.saucedemo.com/');
    await expect(page.locator('[data-test="login-container"]').isVisible()).toBeTruthy();
  });
});
